// One entry point, two jobs. A workflow asks "may I spend?" before a model
// call and reports "I spent this" after it. Both arrive here, so the caller
// only ever wires one sub-workflow in.
const j = $json || {};

function pick(keys, fallback) {
  for (const k of keys) {
    const v = j[k];
    if (v !== undefined && v !== null && String(v).trim() !== '') return v;
  }
  return fallback;
}

const action = String(pick(['action'], 'record')).trim().toLowerCase();
if (['check', 'record'].indexOf(action) === -1) {
  throw new Error('action must be check or record. Received: ' + action);
}

const workflow = String(pick(['workflow', 'workflowName', 'caller'], '')).trim();
if (!workflow) {
  throw new Error('workflow is required so spend can be attributed to something.');
}

// Accept the shapes the different providers and the n8n AI nodes return, so
// the caller can pass the usage object straight through.
const usage = j.usage || j.tokenUsage || {};
function tok(keys) {
  for (const k of keys) {
    if (usage[k] !== undefined && usage[k] !== null) return Number(usage[k]) || 0;
    if (j[k] !== undefined && j[k] !== null) return Number(j[k]) || 0;
  }
  return 0;
}

return [{
  json: {
    action: action,
    workflow: workflow,
    model: String(pick(['model', 'modelName'], 'unknown')).trim(),
    promptTokens: tok(['promptTokens', 'prompt_tokens', 'input_tokens', 'inputTokens']),
    completionTokens: tok(['completionTokens', 'completion_tokens', 'output_tokens', 'outputTokens']),
    estimatedUsd: Number(pick(['estimatedUsd'], 0)) || 0,
    estimatedTokens: Number(pick(['estimatedTokens'], 0)) || 0,
    receivedAt: new Date().toISOString(),
  },
}];

// Work out which budget this caller sits under and what day it is for them,
// then look the ledger up under one stable key.
const req = $('Read The Request').first().json;
const budgets = $('Load Budgets').all().map(function (i) { return i.json; });

if (!budgets.length) {
  throw new Error('The Budgets tab is empty. Add at least a row named default before using this.');
}

const exact = budgets.find(function (b) {
  return String(b['Workflow'] || '').trim().toLowerCase() === req.workflow.toLowerCase();
});
const fallback = budgets.find(function (b) {
  return String(b['Workflow'] || '').trim().toLowerCase() === 'default';
});
const budget = exact || fallback;

if (!budget) {
  throw new Error('No budget row for "' + req.workflow + '" and no default row to fall back on.');
}

// A daily cap needs a day boundary the team recognises, not UTC midnight.
const offset = String(budget['UTC Offset'] || '+00:00').trim();
const m = offset.match(/^([+-])(\d{2}):(\d{2})$/);
const mins = m ? (m[1] === '-' ? -1 : 1) * (Number(m[2]) * 60 + Number(m[3])) : 0;
const local = new Date(Date.now() + mins * 60000);
const day = local.toISOString().slice(0, 10);

return [{
  json: Object.assign({}, req, {
    budgetFor: String(budget['Workflow'] || 'default'),
    capUsd: Number(budget['Daily Cap USD'] || 0) || 0,
    warnAtPercent: Math.max(1, Math.min(99, Number(budget['Warn At Percent'] || 80) || 80)),
    slackChannel: String(budget['Slack Channel'] || '').trim(),
    unknownModelUsdPerMillion: Number(budget['Unknown Model USD Per Million'] || 10) || 10,
    day: day,
    dayKey: req.workflow + '|' + day,
  }),
}];

// The pre-flight answer. A caller asks before it spends, so a runaway loop is
// stopped at the next call rather than discovered on the monthly invoice.
const r = $('Resolve Budget And Day').first().json;
const row = $json || {};

const spent = Number(row.usd || 0) || 0;
const cap = r.capUsd;

// An estimate in dollars wins; otherwise price the estimated tokens at the
// unknown-model rate, which is deliberately pessimistic.
const estimate = r.estimatedUsd > 0
  ? r.estimatedUsd
  : (r.estimatedTokens / 1000000) * r.unknownModelUsdPerMillion;

const projected = spent + estimate;
const allowed = cap <= 0 ? true : projected <= cap;
const remaining = cap <= 0 ? null : Math.max(0, cap - spent);

let reason = 'Within budget.';
if (cap <= 0) reason = 'No cap set for this workflow, so nothing is blocked.';
else if (!allowed && spent >= cap) reason = 'The daily cap of ' + cap + ' USD is already spent.';
else if (!allowed) reason = 'This call would take the day past its ' + cap + ' USD cap.';

return [{
  json: {
    action: 'check',
    workflow: r.workflow,
    day: r.day,
    allowed: allowed,
    spentTodayUsd: Math.round(spent * 10000) / 10000,
    capUsd: cap,
    remainingUsd: remaining === null ? null : Math.round(remaining * 10000) / 10000,
    estimatedUsd: Math.round(estimate * 10000) / 10000,
    reason: reason,
  },
}];

// Price the call that just happened. Prices live in a sheet rather than in
// this code, because they change every few weeks and a hardcoded rate quietly
// stops being true.
const r = $('Resolve Budget And Day').first().json;
const row = $json || {};
const prices = $('Load Model Prices').all().map(function (i) { return i.json; });

const want = r.model.toLowerCase();

// Exact name first, then the longest prefix match, so a dated model id like
// gpt-4.1-mini-2026-03 still prices against gpt-4.1-mini.
let hit = prices.find(function (p) { return String(p['Model'] || '').trim().toLowerCase() === want; });
if (!hit) {
  const candidates = prices
    .filter(function (p) { return want.indexOf(String(p['Model'] || '').trim().toLowerCase()) === 0; })
    .sort(function (a, b) { return String(b['Model']).length - String(a['Model']).length; });
  hit = candidates[0];
}

const priced = !!hit;
const inRate = priced ? Number(hit['Input USD Per Million'] || 0) || 0 : r.unknownModelUsdPerMillion;
const outRate = priced ? Number(hit['Output USD Per Million'] || 0) || 0 : r.unknownModelUsdPerMillion;

// An unpriced model must never count as free. Counting it as zero is how a
// budget silently stops working the week a new model ships.
const usd = (r.promptTokens / 1000000) * inRate + (r.completionTokens / 1000000) * outRate;

const spentBefore = Number(row.usd || 0) || 0;
const calls = Number(row.calls || 0) || 0;
const warned = String(row.warned || 'no') === 'yes';
const blocked = String(row.blocked || 'no') === 'yes';

const total = spentBefore + usd;
const cap = r.capUsd;
const percent = cap > 0 ? Math.round(total / cap * 100) : 0;

let state = 'ok';
if (cap > 0 && total >= cap) state = 'over';
else if (cap > 0 && percent >= r.warnAtPercent) state = 'warning';

// Alert on the crossing, not on every call after it.
const alertKind = (state === 'over' && !blocked) ? 'over'
  : (state === 'warning' && !warned) ? 'warning' : '';

return [{
  json: {
    action: 'record',
    workflow: r.workflow,
    day: r.day,
    dayKey: r.dayKey,
    model: r.model,
    priced: priced,
    promptTokens: r.promptTokens,
    completionTokens: r.completionTokens,
    callUsd: Math.round(usd * 10000) / 10000,
    spentTodayUsd: Math.round(total * 10000) / 10000,
    capUsd: cap,
    percentOfCap: percent,
    remainingUsd: cap > 0 ? Math.round(Math.max(0, cap - total) * 10000) / 10000 : null,
    calls: calls + 1,
    state: state,
    alertKind: alertKind,
    shouldAlert: alertKind !== '',
    warnedAlready: warned || alertKind === 'warning',
    blockedAlready: blocked || alertKind === 'over',
    slackChannel: r.slackChannel,
    alertText: alertKind === 'over'
      ? '*AI budget spent: ' + r.workflow + '*\n' + Math.round(total * 100) / 100 + ' USD of a ' + cap +
        ' USD daily cap. Further calls from this workflow will be refused until ' + r.day + ' ends.' +
        (priced ? '' : '\nThe last model, ' + r.model + ', is not in the price sheet and was charged at the fallback rate.')
      : alertKind === 'warning'
        ? '*AI budget at ' + percent + ' percent: ' + r.workflow + '*\n' + Math.round(total * 100) / 100 +
          ' USD of a ' + cap + ' USD daily cap, with ' + Math.round((cap - total) * 100) / 100 + ' USD left today.'
        : '',
  },
}];

// Yesterday in one message: what each workflow cost, which ones hit their cap,
// and anything that was charged at the fallback rate because its model is
// missing from the price sheet.
const rows = $input.all().map(function (i) { return i.json; }).filter(function (r) { return r && r.workflow; });

if (!rows.length) {
  return [{ json: { skip: true, slackText: '' } }];
}

const day = rows[0].date || '';
const total = rows.reduce(function (s, r) { return s + (Number(r.usd) || 0); }, 0);
const calls = rows.reduce(function (s, r) { return s + (Number(r.calls) || 0); }, 0);

const sorted = rows.slice().sort(function (a, b) { return (Number(b.usd) || 0) - (Number(a.usd) || 0); });
const capped = sorted.filter(function (r) { return String(r.blocked || 'no') === 'yes'; });

const lines = ['*AI spend for ' + day + '*'];
lines.push(Math.round(total * 100) / 100 + ' USD across ' + calls + ' model calls and ' + rows.length + ' workflows.');
lines.push('');
sorted.slice(0, 10).forEach(function (r) {
  lines.push('- ' + r.workflow + ': ' + (Math.round((Number(r.usd) || 0) * 100) / 100) + ' USD over ' + (r.calls || 0) + ' calls' +
    (String(r.blocked || 'no') === 'yes' ? ' (hit its cap)' : ''));
});
if (sorted.length > 10) lines.push('- and ' + (sorted.length - 10) + ' more');
if (capped.length) {
  lines.push('');
  lines.push(capped.length + ' workflow' + (capped.length > 1 ? 's' : '') + ' stopped on the cap yesterday. Raise the cap or find out why they ran hot.');
}

return [{ json: { skip: false, day: day, totalUsd: Math.round(total * 100) / 100, workflows: rows.length, slackText: lines.join('\n') } }];
